window.__vaultPreview("d367ea2c05b4fa9a",{"text":"import re, json, time, sys, os, collections\nimport urllib.request, urllib.error, ssl\nfrom html.parser import HTMLParser\nfrom urllib.parse import urljoin, urlparse\n\nBASE = \"https://alphaletetrenchless.com\"\nUA = \"Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/128.0 Safari/537.36 TAG-SEO-Audit\"\nOUT = os.path.dirname(os.path.abspath(__file__))\nctx = ssl.create_default_context()\n\nclass NoRedirect(urllib.request.HTTPRedirectHandler):\n    def redirect_request(self, req, fp, code, msg, headers, newurl):\n        return None\nopener = urllib.request.build_opener(NoRedirect, urllib.request.HTTPSHandler(context=ctx))\n\ndef fetch(url, timeout=30):\n    req = urllib.request.Request(url, headers={\"User-Agent\": UA, \"Accept\": \"text/html,application/xml\"})\n    t0 = time.time()\n    try:\n        r = opener.open(req, timeout=timeout)\n        body = r.read()\n        return r.status, dict(r.headers), body, time.time() - t0\n    except urllib.error.HTTPError as e:\n        try: body = e.read()\n        except Exception: body = b\"\"\n        return e.code, dict(e.headers), body, time.time() - t0\n    except Exception as e:\n        return 0, {}, str(e).encode(), time.time() - t0\n\ndef chain(url, maxhops=6):\n    hops = []\n    cur = url\n    for _ in range(maxhops):\n        st, h, b, dt = fetch(cur)\n        hops.append((cur, st))\n        if st in (301, 302, 303, 307, 308):\n            loc = h.get(\"Location\") or h.get(\"location\")\n            if not loc: break\n            cur = urljoin(cur, loc)\n            continue\n        return hops, st, h, b, dt\n    return hops, hops[-1][1], {}, b\"\", 0\n\nclass P(HTMLParser):\n    def __init__(self):\n        super().__init__(convert_charrefs=True)\n        self.title = \"\"; self.in_title = False\n        self.meta = {}; self.canon = []; self.h = []; self.cur_h = None; self.buf = \"\"\n        self.links = []; self.jsonld = []; self.in_ld = False; self.ldbuf = \"\"\n        self.skip = 0; self.text = []; self.forms = []; self.tel = []; self.imgs = []\n        self.otto = False\n    def handle_starttag(self, tag, a):\n        a = dict(a)\n        if tag == \"title\": self.in_title = True\n        elif tag == \"meta\":\n            n = (a.get(\"name\") or a.get(\"property\") or \"\").lower()\n            if n: self.meta.setdefault(n, a.get(\"content\", \"\"))\n        elif tag == \"link\" and (a.get(\"rel\") or \"\").lower() == \"canonical\":\n            self.canon.append(a.get(\"href\", \"\"))\n        elif tag in (\"h1\", \"h2\", \"h3\"):\n            self.cur_h = tag; self.buf = \"\"\n        elif tag == \"a\":\n            href = a.get(\"href\") or \"\"\n            self.links.append((href, a.get(\"rel\") or \"\"))\n            if href.startswith(\"tel:\"): self.tel.append(href)\n        elif tag == \"script\":\n            t = (a.get(\"type\") or \"\").lower()\n            if \"ld+json\" in t: self.in_ld = True; self.ldbuf = \"\"\n            else: self.skip += 1\n            if a.get(\"data-otto-pixel\"): self.otto = True\n        elif tag in (\"style\", \"noscript\"): self.skip += 1\n        elif tag == \"form\": self.forms.append(a.get(\"class\", \"\") + \"|\" + a.get(\"data-form-name\", \"\"))\n        elif tag == \"img\": self.imgs.append((a.get(\"src\") or a.get(\"data-src\") or \"\", a.get(\"alt\")))\n    def handle_endtag(self, tag):\n        if tag == \"title\": self.in_title = False\n        elif tag == self.cur_h:\n            self.h.append((tag, re.sub(r\"\\s+\", \" \", self.buf).strip())); self.cur_h = None\n        elif tag == \"script\":\n            if self.in_ld:\n                self.jsonld.append(self.ldbuf); self.in_ld = False\n            elif self.skip: self.skip -= 1\n        elif tag in (\"style\", \"noscript\") and self.skip: self.skip -= 1\n    def handle_data(self, d):\n        if self.in_title: self.title += d\n        if self.cur_h: self.buf += d\n        if self.in_ld: self.ldbuf += d\n        elif not self.skip: self.text.append(d)\n\ndef ld_types(blocks):\n    types = []\n    def walk(o):\n        if isinstance(o, dict):\n            t = o.get(\"@type\")\n            if t: types.extend(t if isinstance(t, list) else [t])\n            for v in o.values(): walk(v)\n        elif isinstance(o, list):\n            for v in o: walk(v)\n    for b in blocks:\n        try: walk(json.loads(b))\n        except Exception: types.append(\"PARSE_ERR\")\n    return types\n\ndef norm(u):\n    p = urlparse(u)\n    return p.scheme + \"://\" + p.netloc + p.path\n\ndef sitemap_urls():\n    urls = []\n    st, h, b, _ = fetch(BASE + \"/sitemap_index.xml\")\n    idx = b.decode(\"utf-8\", \"ignore\")\n    subs = re.findall(r\"<loc>\\s*([^<]+?)\\s*</loc>\", idx)\n    sm = {}\n    for s in subs:\n        if s.endswith(\".xml\") or \"sitemap\" in s:\n            st2, h2, b2, _ = fetch(s)\n            locs = re.findall(r\"<loc>\\s*([^<]+?)\\s*</loc>\", b2.decode(\"utf-8\", \"ignore\"))\n            locs = [l for l in locs if not re.search(r\"\\.(jpg|jpeg|png|webp|gif|svg)$\", l, re.I)]\n            sm[s] = (st2, locs)\n            urls += locs\n        else:\n            urls.append(s)\n    return st, sm, list(dict.fromkeys(urls))\n\ndef analyze(url):\n    hops, st, h, body, dt = chain(url)\n    rec = {\"url\": url, \"status_first\": hops[0][1], \"final_status\": st, \"hops\": len(hops) - 1,\n           \"chain\": \" > \".join(f\"{u.replace(BASE,'')}[{s}]\" for u, s in hops), \"final_url\": hops[-1][0],\n           \"ttfb_s\": round(dt, 2), \"x_robots\": h.get(\"X-Robots-Tag\", h.get(\"x-robots-tag\", \"\")),\n           \"cache\": h.get(\"x-litespeed-cache\", h.get(\"X-LiteSpeed-Cache\", \"\")), \"otto_cache\": h.get(\"x-metasync-otto-cache\", \"\")}\n    if st == 200 and body:\n        html = body.decode(\"utf-8\", \"ignore\")\n        p = P()\n        try: p.feed(html)\n        except Exception as e: rec[\"parse_err\"] = str(e)\n        text = re.sub(r\"\\s+\", \" \", \" \".join(p.text)).strip()\n        rec.update({\n            \"title\": re.sub(r\"\\s+\", \" \", p.title).strip(), \"title_len\": len(p.title.strip()),\n            \"meta_desc\": p.meta.get(\"description\", \"\"), \"meta_len\": len(p.meta.get(\"description\", \"\")),\n            \"robots\": p.meta.get(\"robots\", \"\"), \"canonical\": \";\".join(p.canon),\n            \"h1\": [x[1] for x in p.h if x[0] == \"h1\"], \"h2\": [x[1] for x in p.h if x[0] == \"h2\"][:25],\n            \"h3_count\": sum(1 for x in p.h if x[0] == \"h3\"),\n            \"words\": len(text.split()), \"schema\": sorted(set(ld_types(p.jsonld))), \"schema_blocks\": len(p.jsonld),\n            \"forms\": p.forms, \"tel\": sorted(set(p.tel)), \"otto_pixel\": p.otto or (\"data-otto-pixel\" in html),\n            \"gtm\": \"GTM-\" in html, \"imgs\": len(p.imgs), \"imgs_no_alt\": sum(1 for s, a in p.imgs if not a),\n            \"html_kb\": round(len(body) / 1024), \"text\": text,\n        })\n        internal = []\n        for href, rel in p.links:\n            if not href or href.startswith((\"#\", \"mailto:\", \"tel:\", \"javascript:\")): continue\n            full = urljoin(rec[\"final_url\"], href)\n            if urlparse(full).netloc.replace(\"www.\", \"\") == \"alphaletetrenchless.com\":\n                internal.append((norm(full), \"nofollow\" in rel.lower()))\n        rec[\"internal_links\"] = internal\n    return rec\n\nif __name__ == \"__main__\":\n    st, sm, urls = sitemap_urls()\n    extra = [l.strip() for l in open(os.path.join(OUT, \"extra_urls.txt\")) if l.strip()] if os.path.exists(os.path.join(OUT, \"extra_urls.txt\")) else []\n    allu = list(dict.fromkeys(urls + [BASE + e if e.startswith(\"/\") else e for e in extra]))\n    print(\"sitemap index status\", st, \"subs\", {k: (v[0], len(v[1])) for k, v in sm.items()}, \"urls\", len(urls), \"total\", len(allu), flush=True)\n    json.dump({k: v[1] for k, v in sm.items()}, open(os.path.join(OUT, \"sitemap_urls.json\"), \"w\"), indent=1)\n    res = []\n    for i, u in enumerate(allu):\n        r = analyze(u)\n        r[\"in_sitemap\"] = u in urls\n        res.append(r)\n        if i % 20 == 0: print(i, u, r[\"final_status\"], flush=True)\n        time.sleep(0.4)\n    # discover internal links not in list\n    seen = set(norm(r[\"final_url\"]) for r in res) | set(allu)\n    disc = collections.Counter()\n    for r in res:\n        for l, nf in r.get(\"internal_links\", []):\n            if l not in seen and not re.search(r\"\\.(jpg|jpeg|png|webp|gif|svg|pdf|css|js|xml)$\", l, re.I) and \"/wp-\" not in l:\n                disc[l] += 1\n    newurls = [u for u in disc if u.startswith(BASE)]\n    print(\"discovered non-listed internal URLs:\", len(newurls), flush=True)\n    for u in newurls[:150]:\n        r = analyze(u); r[\"in_sitemap\"] = False; r[\"discovered_via_links\"] = disc[u]; res.append(r); time.sleep(0.4)\n    json.dump(res, open(os.path.join(OUT, \"crawl.json\"), \"w\"), indent=0)\n    print(\"done\", len(res))\n"});
